draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Lessons', W/2, H/2);
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 60);
  ctx.lineTo(W/2, H);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Apply', W/2, H - 20 + 20 * Math.sin(t));
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 + 60);
  ctx.lineTo(W/2 - 30, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2 + 60);
  ctx.lineTo(W/2 + 30, H/2 + 80);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '18px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText('Life', W/2 - 40, H/2 + 70);
  ctx.textAlign = 'right';
  ctx.fillText('Wisdom', W/2 + 40, H/2 + 70);
  ctx.restore();
}
